const float curvature = .01;
const float size_step = 10.;

const int octaves = 3;
const int angles = 3;

vec2 rotate(vec2 pos, float angle) {
    float c = cos(angle), s = sin(angle);

    return vec2(c*pos.x - s*pos.y, s*pos.x + c*pos.y);
}

float get_height(vec2 uv) {
    float h = 1.;

    float a = 1.;
    for (int m = 1; m <= octaves; m++) {
        float mult = float(m)*size_step;

        for (int i = 0; i < angles; i++, a += 1.) {
            vec2 pos = rotate(uv, a + sin(uv.x*a + uv.y*mult)*curvature);
            float crease = -clamp((abs(mod(pos.x*mult, 1.)-.5)-.4)*10., 0., 1.);
            h += crease;
        }
    }

    return clamp(h, 0., 1.);
}

vec3 get_normal(vec2 uv) {
    // convolution
    vec2 pixel = vec2(1., 1.)/iResolution.xy;

    float left = get_height(uv+vec2(-pixel.x, 0.));
    float right = get_height(uv+vec2(pixel.x, 0.));
    float top = get_height(uv+vec2(0., -pixel.y));
    float bottom = get_height(uv+vec2(0., pixel.y));

    return normalize(vec3(left-right, top-bottom, 2.));
}

vec4 to_color(vec3 normal) {
    // converts a normal vector to a color
    return vec4(normal*.5 + .5, 1.);
}

vec4 to_grayscale(float height) {
    // converts a height to a grayscale color (height is assumed to go from 0. to 1.)
    return vec4(height, height, height, 1.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    fragColor = to_color(get_normal(uv));
    //fragColor = to_grayscale(get_height(uv));
}
